@Service
public class SimExpiryCommands {
    private record SourceTarget(String kind,String id,LocalDate expiresOn,long revision) { }
    private record OpenRound(String id,LocalDate expiresOn,LocalDate lastRemindedOn,long count,long revision) { }
    private static final java.time.format.DateTimeFormatter UTC_MICROS=new java.time.format.DateTimeFormatterBuilder().appendInstant(6).toFormatter(Locale.ROOT);
    private record SourceSnapshot(LocalDate expiresOn,long revision) { }
    private final JdbcTemplate jdbc;private final ManagementGuard guard;private final IdempotencyStore idem;private final AuditService audit;private final DatabaseTime clock;private final TransactionRequirements tx;private final SimExpiryQueries queries;
    public SimExpiryCommands(JdbcTemplate jdbc,ManagementGuard guard,IdempotencyStore idem,AuditService audit,DatabaseTime clock,TransactionRequirements tx,SimExpiryQueries queries){this.jdbc=jdbc;this.guard=guard;this.idem=idem;this.audit=audit;this.clock=clock;this.tx=tx;this.queries=queries;}
    private void tenantLock(String tenant){var rows=jdbc.query("SELECT enabled FROM tenants WHERE id=? FOR UPDATE",(r,n)->r.getBoolean(1),tenant);if(rows.isEmpty())throw new ApiError(404,"NOT_FOUND","单位不存在");if(!rows.getFirst())throw new ApiError(403,"UNIT_DISABLED","单位已停用");}
    private static List<Object> fp(Object...args){return Arrays.asList(args);}
    private static String stamp(OffsetDateTime value){return UTC_MICROS.format(value.toInstant());}
    private static boolean fixedTimestamp(String value){if(value==null||value.length()!=27||value.startsWith("0000-"))return false;try{return UTC_MICROS.format(java.time.Instant.from(UTC_MICROS.parse(value))).equals(value);}catch(java.time.DateTimeException e){return false;}}
    private <T>T replay(AuthService.Identity a,String op,String key,String hash,Class<T> c){try{T value=idem.replay(a.user().id(),op,key,hash,c);if(value==null)return null;var saved=jdbc.queryForList("SELECT response_json FROM idempotency_records WHERE user_id=? AND operation=? AND idem_key=?",String.class,a.user().id(),op,key);if(saved.size()!=1||!saved.getFirst().equals(idem.json(value))||!validReplay(value))throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","幂等回执无法确认");return value;}catch(IllegalArgumentException|IllegalStateException e){throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","幂等回执无法确认");}}
    private boolean validReplay(Object value){
        if(value instanceof Config c)return c.tenant_id()!=null&&!c.tenant_id().isEmpty()&&c.revision()>=1&&c.revision()<=9_007_199_254_740_991L&&fixedTimestamp(c.updated_at())&&(c.enabled()?complete(c):complete(c)||empty(c));
        if(value instanceof Recipient r)return r.user_id()!=null&&!r.user_id().isEmpty()&&r.user_id().length()<=64&&fixedTimestamp(r.added_at());
        if(value instanceof Round r)return validRound(r);
        if(value instanceof ReadReceipt r)return r.round_id()!=null&&r.round_id().matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}")&&r.user_id()!=null&&!r.user_id().isEmpty()&&fixedTimestamp(r.read_at());
        if(value instanceof Scan s)return s.created()>=0&&s.repeated()>=0&&s.superseded()>=0&&(s.today()==null?s.created()==0&&s.repeated()==0&&s.superseded()==0:year(s.today()));
        return value instanceof Map<?,?>;
    }
    private boolean complete(Config c){return c.timezone()!=null&&ZoneId.getAvailableZoneIds().contains(c.timezone())&&c.lead_days()!=null&&c.lead_days()>=0&&c.repeat_interval_days()!=null&&c.repeat_interval_days()>=1&&c.repeat_count()!=null&&c.repeat_count()>=0;}
    private boolean empty(Config c){return !c.enabled()&&c.timezone()==null&&c.lead_days()==null&&c.repeat_interval_days()==null&&c.repeat_count()==null;}
    private boolean validRound(Round r){boolean handled="HANDLED".equals(r.state());boolean state=r.state()!=null&&Set.of("OPEN","HANDLED","SUPERSEDED").contains(r.state());boolean target="CARD".equals(r.target_kind())?uuid(r.target_id()):"EMBEDDED".equals(r.target_kind())&&r.target_id()!=null&&!r.target_id().isEmpty()&&r.target_id().length()<=64&&!control(r.target_id());boolean handledFields=handled?r.handled_at()!=null&&r.handled_by()!=null&&r.handle_reason()!=null&&!r.handle_reason().isBlank()&&validReason(r.handle_reason()):r.handled_at()==null&&r.handled_by()==null&&r.handle_reason()==null;boolean reopen=(r.reopened_from()==null&&r.reopen_reason()==null)||(uuid(r.reopened_from())&&r.reopen_reason()!=null&&!r.reopen_reason().isBlank()&&validReason(r.reopen_reason()));return uuid(r.id())&&r.tenant_id()!=null&&target&&year(r.expires_on())&&r.generation()>=1&&state&&r.revision()>=1&&r.revision()<=9_007_199_254_740_991L&&r.reminder_count()>=1&&year(r.last_reminded_on())&&fixedTimestamp(r.opened_at())&&(r.handled_at()==null||fixedTimestamp(r.handled_at()))&&handledFields&&reopen&&r.read_by_me()==(r.read_at()!=null)&&(r.read_at()==null||fixedTimestamp(r.read_at()));}
    private static boolean validReason(String value){if(value==null||value.length()>Limits.MAX_CHANGE_REASON_LENGTH||value.chars().anyMatch(c->Character.isISOControl(c)&&c!='\r'&&c!='\n'&&c!='\t'))return false;try{java.nio.charset.StandardCharsets.UTF_8.newEncoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).encode(java.nio.CharBuffer.wrap(value));return true;}catch(java.nio.charset.CharacterCodingException e){return false;}}
    private static boolean uuid(String value){return value!=null&&value.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}");}
    private static boolean control(String value){return value.chars().anyMatch(Character::isISOControl);}
    private static boolean year(LocalDate value){return value!=null&&value.getYear()>=1&&value.getYear()<=9999;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Config configure(AuthService.Identity actor,String tenant,String key,ConfigInput in,String request){tx.readCommitted();guard.begin(actor,"sim-expiry:write",tenant,"management");guard.requireCurrent(actor,"sim-expiry:read",tenant,"management");idem.validateKey(key);String op="sim-expiry:config",hash=idem.fingerprint(fp(tenant,in.enabled(),in.timezone(),in.leadDays(),in.repeatIntervalDays(),in.repeatCount(),in.expectedRevision(),in.reason()));Config old=replay(actor,op,key,hash,Config.class);if(old!=null){if(!old.tenant_id().equals(tenant)||old.revision()!=in.expectedRevision()+1||old.enabled()!=in.enabled()||!Objects.equals(old.timezone(),in.timezone())||!Objects.equals(old.lead_days(),in.leadDays())||!Objects.equals(old.repeat_interval_days(),in.repeatIntervalDays())||!Objects.equals(old.repeat_count(),in.repeatCount()))throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","配置回执无法确认");return old;}tenantLock(tenant);Config current=queries.config(tenant);if(current.revision()!=in.expectedRevision())throw ApiError.conflict("REVISION_CONFLICT","到期提醒配置已更新");if(current.revision()>=9007199254740991L)throw ApiError.conflict("SIM_EXPIRY_REVISION_EXHAUSTED","配置版本已耗尽");OffsetDateTime now=clock.now();long rev=current.revision()+1;if(current.revision()==0)jdbc.update("INSERT INTO sim_expiry_config(tenant_id,enabled,timezone,lead_days,repeat_interval_days,repeat_count,revision,updated_at) VALUES (?,?,?,?,?,?,?,?)",tenant,in.enabled(),in.timezone(),in.leadDays(),in.repeatIntervalDays(),in.repeatCount(),rev,now);else jdbc.update("UPDATE sim_expiry_config SET enabled=?,timezone=?,lead_days=?,repeat_interval_days=?,repeat_count=?,revision=?,updated_at=? WHERE tenant_id=? AND revision=?",in.enabled(),in.timezone(),in.leadDays(),in.repeatIntervalDays(),in.repeatCount(),rev,now,tenant,current.revision());Config result=queries.config(tenant);audit.record(actor.user().id(),tenant,op,tenant,"SUCCESS",request);idem.save(actor.user().id(),op,key,hash,result);return result;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Recipient addRecipient(AuthService.Identity actor,String tenant,String key,RecipientInput in,String request){tx.readCommitted();guard.begin(actor,"sim-expiry:write",tenant,"management");guard.requireCurrent(actor,"sim-expiry:read",tenant,"management");idem.validateKey(key);String op="sim-expiry:recipient-add",hash=idem.fingerprint(fp(tenant,in.userId()));Recipient replayed=replay(actor,op,key,hash,Recipient.class);if(replayed!=null){if(!replayed.user_id().equals(in.userId())||!replayed.eligible())throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","收件人回执无法确认");return replayed;}tenantLock(tenant);if(!queries.eligible(in.userId(),tenant))throw ApiError.bad("目标用户当前不具备到期提醒资格");var old=queries.recipient(tenant,in.userId());if(old==null)jdbc.update("INSERT INTO sim_expiry_recipients(tenant_id,user_id,added_at,added_by) VALUES (?,?,?,?)",tenant,in.userId(),clock.now(),actor.user().id());Recipient result=queries.recipient(tenant,in.userId());audit.record(actor.user().id(),tenant,op,in.userId(),"SUCCESS",request);idem.save(actor.user().id(),op,key,hash,result);return result;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Map<String,Object> removeRecipient(AuthService.Identity actor,String tenant,String user,String key,String request){tx.readCommitted();guard.begin(actor,"sim-expiry:write",tenant,"management");guard.requireCurrent(actor,"sim-expiry:read",tenant,"management");idem.validateKey(key);String op="sim-expiry:recipient-remove",hash=idem.fingerprint(fp(tenant,user));@SuppressWarnings("unchecked") Map<String,Object> old=replay(actor,op,key,hash,Map.class);if(old!=null){if(!old.keySet().equals(Set.of("user_id","removed"))||!user.equals(old.get("user_id"))||!(old.get("removed") instanceof Boolean))throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","移除回执无法确认");return old;}tenantLock(tenant);boolean removed=jdbc.update("DELETE FROM sim_expiry_recipients WHERE tenant_id=? AND user_id=?",tenant,user)>0;Map<String,Object> result=Map.of("user_id",user,"removed",removed);audit.record(actor.user().id(),tenant,op,user,"SUCCESS",request);idem.save(actor.user().id(),op,key,hash,result);return result;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Scan scanTenant(String tenant){tx.readCommitted();jdbc.queryForObject("SELECT id FROM security_management_lock WHERE id=1 FOR UPDATE",Integer.class);var tenants=jdbc.query("SELECT id,enabled FROM tenants WHERE id=? FOR UPDATE",(r,n)->new Object[]{r.getString(1),r.getBoolean(2)},tenant);if(tenants.isEmpty())throw new ApiError(404,"NOT_FOUND","单位不存在");if(!(boolean)tenants.getFirst()[1])return new Scan(null,0,0,0);if(!scanEffective(tenant))return scanLocked(tenant);lockSources(tenant);int orphaned=supersedeMissingSources(tenant);Scan result=scanLocked(tenant);return new Scan(result.today(),result.created(),result.repeated(),result.superseded()+orphaned);}
    private boolean scanEffective(String tenant){if(!queries.config(tenant).enabled())return false;Long count=jdbc.queryForObject("SELECT COUNT(*) FROM sim_expiry_recipients r JOIN app_users u ON u.id=r.user_id AND u.user_type='PLATFORM' AND u.enabled=TRUE AND u.must_change_password=FALSE JOIN user_tenant_grants g ON g.user_id=u.id AND g.tenant_id=r.tenant_id JOIN effective_user_permissions p ON p.user_id=u.id AND p.permission='sim-expiry:read' WHERE r.tenant_id=?",Long.class,tenant);return count>0;}
    private void lockSources(String tenant){jdbc.query("SELECT id FROM sim_cards WHERE tenant_id=? ORDER BY id FOR UPDATE",(r,n)->r.getString(1),tenant);jdbc.query("SELECT device_id FROM sim_embedded_profiles WHERE tenant_id=? ORDER BY device_id FOR UPDATE",(r,n)->r.getString(1),tenant);}
    private int supersedeMissingSources(String tenant){
        if(!queries.config(tenant).enabled())return 0;
        Long active=jdbc.queryForObject("SELECT COUNT(*) FROM sim_expiry_recipients r JOIN app_users u ON u.id=r.user_id AND u.user_type='PLATFORM' AND u.enabled=TRUE AND u.must_change_password=FALSE JOIN user_tenant_grants g ON g.user_id=u.id AND g.tenant_id=r.tenant_id JOIN effective_user_permissions p ON p.user_id=u.id AND p.permission='sim-expiry:read' WHERE r.tenant_id=?",Long.class,tenant);if(active==0)return 0;
        String missing="((r.target_kind='CARD' AND NOT EXISTS(SELECT 1 FROM sim_cards s WHERE s.tenant_id=r.tenant_id AND s.id=r.target_id AND s.expires_on=r.expires_on)) OR (r.target_kind='EMBEDDED' AND NOT EXISTS(SELECT 1 FROM sim_embedded_profiles s WHERE s.tenant_id=r.tenant_id AND s.device_id=r.target_id AND s.expires_on=r.expires_on)))";
        var rows=jdbc.query("SELECT r.id,r.revision FROM sim_expiry_rounds r WHERE r.tenant_id=? AND r.state='OPEN' AND "+missing+" FOR UPDATE",(r,n)->new Object[]{r.getString(1),r.getLong(2)},tenant);int count=0;
        for(Object[] row:rows){String id=(String)row[0];queries.round(tenant,id,null);long revision=(long)row[1];if(revision>=9_007_199_254_740_991L)throw ApiError.conflict("SIM_EXPIRY_REVISION_EXHAUSTED","轮次版本已耗尽");if(jdbc.update("UPDATE sim_expiry_rounds SET state='SUPERSEDED',revision=revision+1 WHERE id=? AND state='OPEN' AND revision=?",id,revision)!=1)throw ApiError.conflict("REVISION_CONFLICT","提醒轮次已更新");count++;}
        return count;
    }
    private SourceTarget sourceTarget(java.sql.ResultSet r)throws java.sql.SQLException{String kind=r.getString(1),id=r.getString(2);LocalDate date=r.getObject(3,LocalDate.class);long revision=r.getLong(4);boolean identity="CARD".equals(kind)?uuid(id):"EMBEDDED".equals(kind)&&id!=null&&!id.isEmpty()&&id.length()<=64&&!control(id);if(!identity||!year(date)||revision<0||revision>9_007_199_254_740_991L)throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","来源到期事实无法确认");return new SourceTarget(kind,id,date,revision);}
    private Scan scanLocked(String tenant){
        Config config=queries.config(tenant);if(!config.enabled())return new Scan(null,0,0,0);
        OffsetDateTime now=clock.now();LocalDate today=now.atZoneSameInstant(ZoneId.of(config.timezone())).toLocalDate();
        Long recipients=jdbc.queryForObject("SELECT COUNT(*) FROM sim_expiry_recipients r JOIN app_users u ON u.id=r.user_id AND u.user_type='PLATFORM' AND u.enabled=TRUE AND u.must_change_password=FALSE JOIN user_tenant_grants g ON g.user_id=u.id AND g.tenant_id=r.tenant_id JOIN effective_user_permissions p ON p.user_id=u.id AND p.permission='sim-expiry:read' WHERE r.tenant_id=?",Long.class,tenant);
        if(recipients==0)return new Scan(today,0,0,0);
        int created=0,repeated=0,superseded=0;
        var targets=jdbc.query("SELECT 'CARD' AS target_kind,id AS target_id,expires_on,revision FROM sim_cards WHERE tenant_id=? AND expires_on IS NOT NULL UNION ALL SELECT 'EMBEDDED',device_id,expires_on,revision FROM sim_embedded_profiles WHERE tenant_id=? AND expires_on IS NOT NULL ORDER BY target_kind,target_id",(r,n)->sourceTarget(r),tenant,tenant);
        for(SourceTarget target:targets){
            String kind=target.kind(),targetId=target.id();LocalDate expires=target.expiresOn();long sourceRevision=target.revision();
            var opens=jdbc.query("SELECT id,expires_on,last_reminded_on,reminder_count,revision FROM sim_expiry_rounds WHERE tenant_id=? AND target_kind=? AND target_id=? AND state='OPEN' FOR UPDATE",(r,n)->new OpenRound(r.getString(1),r.getObject(2,LocalDate.class),r.getObject(3,LocalDate.class),r.getLong(4),r.getLong(5)),tenant,kind,targetId);
            if(opens.size()>1)throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","存在多个未完成提醒轮次");
            if(!opens.isEmpty())queries.round(tenant,opens.getFirst().id(),null);
            if(!opens.isEmpty()&&!expires.equals(opens.getFirst().expiresOn())){
                OpenRound stale=opens.getFirst();queries.round(tenant,stale.id(),null);if(stale.revision()>=9_007_199_254_740_991L)throw ApiError.conflict("SIM_EXPIRY_REVISION_EXHAUSTED","轮次版本已耗尽");
                if(jdbc.update("UPDATE sim_expiry_rounds SET state='SUPERSEDED',revision=revision+1 WHERE id=? AND state='OPEN' AND revision=?",stale.id(),stale.revision())!=1)throw ApiError.conflict("REVISION_CONFLICT","提醒轮次已更新");superseded++;opens=List.of();
            }
            if(opens.isEmpty()){
                Long prior=jdbc.queryForObject("SELECT COUNT(*) FROM sim_expiry_rounds WHERE tenant_id=? AND target_kind=? AND target_id=? AND expires_on=?",Long.class,tenant,kind,targetId,expires);
                boolean changedBack=prior>0&&dateChangedSinceLastRound(tenant,kind,targetId,expires,sourceRevision);
                if((prior==0||changedBack)&&window(expires,today,config.lead_days())){
                    int generation=nextGeneration(tenant,kind,targetId,expires);String round=UUID.randomUUID().toString();
                    jdbc.update("INSERT INTO sim_expiry_rounds(id,tenant_id,target_kind,target_id,expires_on,generation,state,revision,reminder_count,last_reminded_on,opened_at,source_revision) VALUES (?,?,?,?,?,?,'OPEN',1,1,?,?,?)",round,tenant,kind,targetId,expires,generation,today,now,sourceRevision);
                    jdbc.update("INSERT INTO sim_expiry_notices(id,round_id,sequence,noticed_on,kind,created_at) VALUES (?,?,1,?,'INITIAL',?)",UUID.randomUUID().toString(),round,today,now);created++;
                }
                continue;
            }
            OpenRound open=opens.getFirst();LocalDate last=open.lastRemindedOn();long count=open.count(),revision=open.revision();String round=open.id();
            if(!year(last)||count<1||revision<1||count>9_007_199_254_740_991L)throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","提醒轮次无法确认");
            if(!today.isBefore(last)&&java.time.temporal.ChronoUnit.DAYS.between(last,today)>=config.repeat_interval_days()&&count<(long)config.repeat_count()+1){
                if(revision>=9_007_199_254_740_991L)throw ApiError.conflict("SIM_EXPIRY_REVISION_EXHAUSTED","轮次版本已耗尽");
                jdbc.update("INSERT INTO sim_expiry_notices(id,round_id,sequence,noticed_on,kind,created_at) VALUES (?,?,?,?,'REPEAT',?)",UUID.randomUUID().toString(),round,count+1,today,now);
                if(jdbc.update("UPDATE sim_expiry_rounds SET reminder_count=reminder_count+1,last_reminded_on=?,revision=revision+1 WHERE id=? AND state='OPEN' AND revision=?",today,round,revision)!=1)throw ApiError.conflict("REVISION_CONFLICT","提醒轮次已更新");repeated++;
            }
        }
        return new Scan(today,created,repeated,superseded);
    }
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Scan explicitScan(AuthService.Identity actor,String tenant,String key,String request){tx.readCommitted();guard.begin(actor,"sim-expiry:write",tenant,"management");guard.requireCurrent(actor,"sim-expiry:read",tenant,"management");idem.validateKey(key);String op="sim-expiry:scan",hash=idem.fingerprint(fp(tenant));Scan replayed=replay(actor,op,key,hash,Scan.class);if(replayed!=null)return replayed;tenantLock(tenant);boolean effective=scanEffective(tenant);if(effective)lockSources(tenant);int orphaned=effective?supersedeMissingSources(tenant):0;Scan result=scanLocked(tenant);result=new Scan(result.today(),result.created(),result.repeated(),result.superseded()+orphaned);audit.record(actor.user().id(),tenant,op,tenant,"SUCCESS",request);idem.save(actor.user().id(),op,key,hash,result);return result;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public ReadReceipt read(AuthService.Identity actor,String tenant,String id,String key,String request){tx.readCommitted();guard.begin(actor,"sim-expiry:read",tenant,"management");boolean manager=guard.hasCurrentPermission(actor,"sim-expiry:handle")||guard.hasCurrentPermission(actor,"sim-expiry:write");if(!manager&&(!queries.eligible(actor.user().id(),tenant)||queries.recipient(tenant,actor.user().id())==null))throw ApiError.forbidden("当前用户不是有效提醒收件人");idem.validateKey(key);String op="sim-expiry:read-receipt",hash=idem.fingerprint(fp(tenant,id));ReadReceipt replayed=replay(actor,op,key,hash,ReadReceipt.class);if(replayed!=null){if(!replayed.round_id().equals(id)||!replayed.user_id().equals(actor.user().id())||!fixedTimestamp(replayed.read_at()))throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","已读回执无法确认");queries.round(tenant,id,actor.user().id());return replayed;}tenantLock(tenant);queries.round(tenant,id,actor.user().id());if(!manager&&!queries.received(tenant,actor.user().id(),id))throw new ApiError(404,"NOT_FOUND","记录不存在");var old=jdbc.query("SELECT read_at FROM sim_expiry_reads WHERE round_id=? AND user_id=?",(r,n)->r.getObject(1,OffsetDateTime.class),id,actor.user().id());OffsetDateTime readAt=old.isEmpty()?clock.now():old.getFirst();if(old.isEmpty())jdbc.update("INSERT INTO sim_expiry_reads(round_id,user_id,read_at) VALUES (?,?,?)",id,actor.user().id(),readAt);ReadReceipt result=new ReadReceipt(id,actor.user().id(),stamp(readAt));audit.record(actor.user().id(),tenant,op,id,"SUCCESS",request);idem.save(actor.user().id(),op,key,hash,result);return result;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Round handle(AuthService.Identity actor,String tenant,String id,String key,HandleInput in,String request){tx.readCommitted();guard.begin(actor,"sim-expiry:handle",tenant,"management");guard.requireCurrent(actor,"sim-expiry:read",tenant,"management");idem.validateKey(key);String op="sim-expiry:handle",hash=idem.fingerprint(fp(tenant,id,in.reason(),in.expectedRevision()));Round replayed=replay(actor,op,key,hash,Round.class);if(replayed!=null){if(!replayed.id().equals(id)||!replayed.tenant_id().equals(tenant)||!replayed.state().equals("HANDLED")||replayed.revision()!=in.expectedRevision()+1||!actor.user().id().equals(replayed.handled_by())||!in.reason().equals(replayed.handle_reason()))throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","处理回执无法确认");queries.round(tenant,id,actor.user().id());return replayed;}tenantLock(tenant);Round current=queries.round(tenant,id,actor.user().id());if(!current.state().equals("OPEN"))throw ApiError.conflict("SIM_EXPIRY_STATE_CONFLICT","仅开放轮次可处理");if(current.revision()!=in.expectedRevision())throw ApiError.conflict("REVISION_CONFLICT","提醒轮次已更新");if(current.revision()>=9007199254740991L)throw ApiError.conflict("SIM_EXPIRY_REVISION_EXHAUSTED","轮次版本已耗尽");OffsetDateTime now=clock.now();if(jdbc.update("UPDATE sim_expiry_rounds SET state='HANDLED',revision=revision+1,handled_at=?,handled_by=?,handle_reason=? WHERE tenant_id=? AND id=? AND state='OPEN' AND revision=?",now,actor.user().id(),in.reason(),tenant,id,current.revision())!=1)throw ApiError.conflict("REVISION_CONFLICT","提醒轮次已更新");Round result=queries.round(tenant,id,actor.user().id());audit.record(actor.user().id(),tenant,op,id,"SUCCESS",request);idem.save(actor.user().id(),op,key,hash,result);return result;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Round reopen(AuthService.Identity actor,String tenant,String id,String key,HandleInput in,String request){
        tx.readCommitted();guard.begin(actor,"sim-expiry:handle",tenant,"management");guard.requireCurrent(actor,"sim-expiry:read",tenant,"management");idem.validateKey(key);
        String op="sim-expiry:reopen",hash=idem.fingerprint(fp(tenant,id,in.reason(),in.expectedRevision()));Round replayed=replay(actor,op,key,hash,Round.class);if(replayed!=null){if(!tenant.equals(replayed.tenant_id())||!id.equals(replayed.reopened_from())||!in.reason().equals(replayed.reopen_reason())||!replayed.state().equals("OPEN")||replayed.generation()<2||replayed.revision()!=1||replayed.reminder_count()!=1||replayed.read_by_me()||replayed.read_at()!=null)throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","重开回执无法确认");queries.round(tenant,replayed.id(),actor.user().id());return replayed;}
        tenantLock(tenant);Round prior=queries.round(tenant,id,actor.user().id());Long openCount=jdbc.queryForObject("SELECT COUNT(*) FROM sim_expiry_rounds WHERE tenant_id=? AND target_kind=? AND target_id=? AND state='OPEN'",Long.class,tenant,prior.target_kind(),prior.target_id());if(openCount!=0)throw ApiError.conflict("SIM_EXPIRY_STATE_CONFLICT","来源已有未完成提醒轮次");if(!prior.state().equals("HANDLED"))throw ApiError.conflict("SIM_EXPIRY_STATE_CONFLICT","仅已处理轮次可重开");if(prior.revision()!=in.expectedRevision())throw ApiError.conflict("REVISION_CONFLICT","提醒轮次已更新");
        String latest=jdbc.queryForObject("SELECT id FROM sim_expiry_rounds WHERE tenant_id=? AND target_kind=? AND target_id=? AND expires_on=? ORDER BY generation DESC LIMIT 1",String.class,tenant,prior.target_kind(),prior.target_id(),prior.expires_on());if(!id.equals(latest))throw ApiError.conflict("SIM_EXPIRY_STATE_CONFLICT","仅最新轮次可重开");
        SourceSnapshot source=lockSource(tenant,prior.target_kind(),prior.target_id());if(source==null||!prior.expires_on().equals(source.expiresOn()))throw ApiError.conflict("SIM_EXPIRY_STATE_CONFLICT","来源到期日已变化");
        int generation=nextGeneration(tenant,prior.target_kind(),prior.target_id(),prior.expires_on());OffsetDateTime now=clock.now();Config config=queries.config(tenant);if(config.timezone()==null)throw ApiError.conflict("SIM_EXPIRY_STATE_CONFLICT","重开需要已配置的时区");LocalDate today=now.atZoneSameInstant(ZoneId.of(config.timezone())).toLocalDate();
        String fresh=UUID.randomUUID().toString();jdbc.update("INSERT INTO sim_expiry_rounds(id,tenant_id,target_kind,target_id,expires_on,generation,state,revision,reminder_count,last_reminded_on,opened_at,source_revision,reopened_from,reopen_reason) VALUES (?,?,?,?,?,?,'OPEN',1,1,?,?,?,?,?)",fresh,tenant,prior.target_kind(),prior.target_id(),prior.expires_on(),generation,today,now,source.revision(),id,in.reason());
        jdbc.update("INSERT INTO sim_expiry_notices(id,round_id,sequence,noticed_on,kind,created_at) VALUES (?,?,1,?,'INITIAL',?)",UUID.randomUUID().toString(),fresh,today,now);Round result=queries.round(tenant,fresh,actor.user().id());audit.record(actor.user().id(),tenant,op,id,"SUCCESS",request);idem.save(actor.user().id(),op,key,hash,result);return result;
    }
    private SourceSnapshot lockSource(String tenant,String kind,String id){String sql=kind.equals("CARD")?"SELECT expires_on,revision FROM sim_cards WHERE tenant_id=? AND id=? FOR UPDATE":"SELECT expires_on,revision FROM sim_embedded_profiles WHERE tenant_id=? AND device_id=? FOR UPDATE";var rows=jdbc.query(sql,(r,n)->new SourceSnapshot(r.getObject(1,LocalDate.class),r.getLong(2)),tenant,id);if(rows.isEmpty())return null;SourceSnapshot source=rows.getFirst();if(source.revision()<0||source.revision()>9_007_199_254_740_991L||source.expiresOn()!=null&&!year(source.expiresOn()))throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","来源到期事实无法确认");return source;}
    private int nextGeneration(String tenant,String kind,String id,LocalDate date){Long max=jdbc.queryForObject("SELECT COALESCE(MAX(generation),0) FROM sim_expiry_rounds WHERE tenant_id=? AND target_kind=? AND target_id=? AND expires_on=?",Long.class,tenant,kind,id,date);if(max==null||max>=Integer.MAX_VALUE)throw ApiError.conflict("SIM_EXPIRY_REVISION_EXHAUSTED","轮次代次已耗尽");return Math.toIntExact(max+1);}
    private boolean dateChangedSinceLastRound(String tenant,String kind,String id,LocalDate date,long currentRevision){
        Long baseline=jdbc.queryForObject("SELECT source_revision FROM sim_expiry_rounds WHERE tenant_id=? AND target_kind=? AND target_id=? AND expires_on=? ORDER BY generation DESC LIMIT 1",Long.class,tenant,kind,id,date);
        if(baseline==null||baseline<0||baseline>9_007_199_254_740_991L||currentRevision<baseline||currentRevision>9_007_199_254_740_991L)throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","来源版本无法确认");if(currentRevision==baseline)return false;
        String changes=kind.equals("CARD")?"SELECT COUNT(*),COALESCE(SUM(CASE WHEN expires_on IS NULL OR expires_on<>? THEN 1 ELSE 0 END),0) FROM sim_card_changes WHERE tenant_id=? AND card_id=? AND revision>? AND revision<=?":"SELECT COUNT(*),COALESCE(SUM(CASE WHEN expires_on IS NULL OR expires_on<>? THEN 1 ELSE 0 END),0) FROM sim_embedded_profile_changes WHERE tenant_id=? AND device_id=? AND revision>? AND revision<=?";
        long[] facts=jdbc.queryForObject(changes,(r,n)->new long[]{r.getLong(1),r.getLong(2)},date,tenant,id,baseline,currentRevision);
        if(facts[0]!=currentRevision-baseline)throw new ApiError(503,"SIM_EXPIRY_READ_UNCONFIRMED","来源历史无法确认");return facts[1]>0;
    }
    static boolean window(LocalDate date,LocalDate today,int lead){return java.time.temporal.ChronoUnit.DAYS.between(today,date)<=lead;}
}
